"""Generates docs/REPORT.md from committed run outputs, so no number in it is typed by hand."""

from __future__ import annotations

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
RUNS = ROOT / "runs"


def load(name: str):
    path = RUNS / name
    return json.loads(path.read_text(encoding="utf-8")) if path.exists() else None


def main() -> None:
    lines = [
        "# Evidence report",
        "",
        "Generated by `poe report` from `runs/`. Hand edits are overwritten.",
        "",
        "**This is not the final evaluation.** No Deepgram or LLM call has been made, no encoder has been trained, "
        "and the test split hasn't been opened. Every routing number below comes from template fixtures and must not be quoted as a result.",
        "",
        "## Isolation mutation check",
        "",
    ]
    mutation = load("mutation_check.json")
    if mutation:
        caught = sum(m["status"] == "caught" for m in mutation)
        lines += [f"{caught} of {len(mutation)} removed controls were caught by a named failing test.", "", "| Removed control | Result | Caught by |", "|---|---|---|"]
        lines += [f"| {m['name']} | {m['status']} | {m.get('caught_by', '').split(';')[0]} |" for m in mutation]
    failure = load("failure_injection.json")
    lines += ["", "## Failure injection, real SIP calls", ""]
    if failure:
        lines += ["| Scenario | Outcome | Reached |", "|---|---|---|"]
        lines += [f"| {r['scenario']} | {'pass' if r['ok'] else 'FAIL'} | {', '.join(r.get('reached', []))} |" for r in failure]
    load_report = load("load_e2e.json")
    lines += ["", "## SIP load, replay ASR", ""]
    if load_report:
        lines += [
            f"Host: {load_report['host']['processor']}. Cores not pinned, so treat these as indicative.",
            "",
            "**This is not `T_route`.** Replay ASR has no endpointing wait and no network path to Deepgram, which the plan expected to be most of the budget. "
            "These figures cover the gateway's own work from the end-of-speech signal.",
            "",
            "| Calls per second | Offered | Routed | Decision p50 / p95 ms | Route command p50 / p95 ms | SIPp |",
            "|---:|---:|---:|---:|---:|---|",
        ]
        for r in load_report["levels"]:
            d, c = r["eos_to_decision_ms"], r["route_cmd_ms"]
            lines.append(f"| {r['rate_cps']} | {r['calls_offered']} | {r['calls_routed']} | {d['p50']:.2f} / {d['p95']:.2f} | {c['p50']:.1f} / {c['p95']:.1f} | {r['sipp']} |")
    micro = load("micro_tfidf.json")
    if micro:
        lines += ["", "## Stage micro-benchmark", "", f"TF-IDF predict, one thread: p50 {micro['p50_ms']:.2f} ms, p95 {micro['p95_ms']:.2f} ms, p99 {micro['p99_ms']:.2f} ms (n={micro['n']}, stage budget {micro['budget_ms']} ms). Core not pinned."]
    fixture = load("fixture/report.json")
    if fixture:
        lines += ["", "## Fixture evaluation (pipeline check only)", "", f"> {fixture['banner']}", "", "| Arm | Accuracy | Mean cost | Emergency recall | Emergency to voicemail |", "|---|---:|---:|---:|---:|"]
        for name, a in fixture["arms"].items():
            recall = "n/a" if a["emergency_recall"] is None else f"{a['emergency_recall']:.3f}"
            lines.append(f"| {name} | {a['accuracy']:.3f} | {a['mean_cost']:.3f} | {recall} | {a['emergency_to_voicemail']} |")
        lines += ["", "Not run: " + "; ".join(f"`{k}` ({v})" for k, v in fixture["not_run"].items()) + "."]
    (ROOT / "docs/REPORT.md").write_text("\n".join(lines) + "\n", encoding="utf-8", newline="\n")


if __name__ == "__main__":
    main()
